mapper.select:
SELECT u.id,u.email,u.created_at,t.expires_at,
CASE WHEN t.disable_reason='MANUAL' THEN 'DISABLED' WHEN t.expires_at <= #{now} THEN 'EXPIRED' WHEN u.status!='ACTIVE' THEN 'DISABLED' ELSE 'ACTIVE' END status,t.include_in_statistics,u.version
 ORDER BY u.created_at DESC,u.id LIMIT #{limit} OFFSET #{offset}
